CREATE POLICY "Admins can view sponsorship tiers" ON public.sponsorship_tiers FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Anyone can view client demo sponsorship tiers" ON public.sponsorship_tiers FOR SELECT TO anon, authenticated USING (is_active = true AND EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id = sponsorship_tiers.tournament_id AND t.client_sample_id IS NOT NULL));
CREATE POLICY "Anyone can view client demo registration tiers" ON public.tournament_registration_tiers FOR SELECT TO anon, authenticated USING (is_active = true AND EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id = tournament_registration_tiers.tournament_id AND t.client_sample_id IS NOT NULL));
CREATE POLICY "Anyone can view client demo registration fields" ON public.tournament_registration_fields FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id = tournament_registration_fields.tournament_id AND t.client_sample_id IS NOT NULL));